sys_properties.value:
[
  {
    datasources: ["SNOW", "Flexnet", servicenow],
    servicenow: [
      {
        table: "alm_license",
        reports: [
          {
            name: "Total Active Licenses",
            condition: "install_status=1"
          },
          {
            name: "Active Licenses without PPN",
            condition: "install_status=1^publisher_part_number=NULL"
          },
          {
            name: "Active Licenses without Cost",
            condition: "install_status=1^cost=javascript:global.getCurrencyFilter('alm_license','cost', 'INR;0')^ORcost=NULL"
          },
          {
            name: "Active Licenses without License Metric",
            condition: "install_status=1^license_metric=NULL"
          },
          {
            name: "Active Licenses without Software Model",
            condition: "install_status=1^modelISEMPTY"
          }
        ]
      }
    ]
  }
]
